-- Generated from CRAW_DATA/chotot_items_final.json
-- Unique categories: 39
-- ID now uses alphanumeric format (cg-xxxx, at-xxxx), old value moved to slug
BEGIN;

-- Ensure slug columns exist for current schema
ALTER TABLE categories ADD COLUMN IF NOT EXISTS slug VARCHAR(255);
ALTER TABLE category_attributes ADD COLUMN IF NOT EXISTS slug VARCHAR(255);

ON CONFLICT (category_id) DO UPDATE SET
  slug = EXCLUDED.slug,
  name = EXCLUDED.name,
  description = EXCLUDED.description,
  updated_at = EXCLUDED.updated_at;

ON CONFLICT (attribute_id) DO UPDATE SET
  slug = EXCLUDED.slug,
  code = EXCLUDED.code,
  name = EXCLUDED.name,
  description = EXCLUDED.description,
  data_type = EXCLUDED.data_type,
  unit = EXCLUDED.unit,
  required = EXCLUDED.required,
  filterable = EXCLUDED.filterable,
  searchable = EXCLUDED.searchable,
  min_value_number = EXCLUDED.min_value_number,
  max_value_number = EXCLUDED.max_value_number,
  options_json = EXCLUDED.options_json,
  sort_order = EXCLUDED.sort_order,
  updated_at = EXCLUDED.updated_at;

-- Backfill uniqueness for slug (safe if already exists)
CREATE UNIQUE INDEX IF NOT EXISTS uq_categories_slug ON categories(slug);
CREATE UNIQUE INDEX IF NOT EXISTS uq_category_attributes_category_slug ON category_attributes(category_id, slug);

COMMIT;
